import hashlib, pathlib, sys
bad=[]
files=list(pathlib.Path(\".\").rglob(\"*\"))
for line in pathlib.Path(\"SHA256SUMS\").read_text(encoding=\"utf-8\").splitlines():
    line=line.strip()
    if not line: continue
    try:
        digest, rel = line.split(\"  \",1)
    except ValueError:
        try: digest, rel = line.split(\" \",1)
        except ValueError:
            bad.append((line,\"MALFORMED\")); continue
    p=pathlib.Path(rel)
    if not p.exists():
        bad.append((rel,\"MISSING\")); continue
    actual=hashlib.sha256(p.read_bytes()).hexdigest()
    if actual"'!=digest:
        bad.append((rel,f"hash mismatch: listed={digest} actual={actual}"))
print("BAD:", len(bad))
for rel,msg in bad: print(rel, msg)
print("TOTAL LINES:", sum(1 for l in pathlib.Path('"'SHA256SUMS').read_text(encoding='utf-8').splitlines() if l.strip()))
EOF"

